<?php
namespace App\Controllers\Api\V1;
use App\Models\{AvailabilityModel,ContentGroupModel,NoticeModel,SelectableOptionModel,StudyProfileModel,StudySessionModel,SubjectModel,TopicModel};
final class DashboardController extends ApiController
{
 private static function databaseBoolean(mixed $value): bool { return in_array($value,[true,1,'1','t','true'],true); }
 public function index(){ $uid=$this->userId();$noticeId=$this->request->getGet('edital_id');$query=(new NoticeModel())->where('user_id',$uid);
  if($noticeId!==null){if(!ctype_digit((string)$noticeId))return $this->failValidationErrors('Edital inválido.');$notice=$query->where('id',$noticeId)->first();if(!$notice)return $this->failNotFound();}
  else $notice=$query->where('status','confirmed')->first();$materias=[];$opcoes=[];
  if($notice){$optionRows=(new SelectableOptionModel())->where('notice_id',$notice['id'])->orderBy('sort_order')->findAll();foreach($optionRows as $o)$opcoes[]=['id'=>(string)$o['id'],'codigo'=>$o['code'],'nome'=>$o['name'],'tipo'=>$o['kind'],'selecionada'=>self::databaseBoolean($o['is_selected'])];$groups=(new ContentGroupModel())->where('notice_id',$notice['id'])->findAll();$groupById=array_column($groups,null,'id');$subjects=(new SubjectModel())->where('notice_id',$notice['id'])->orderBy('sort_order')->findAll();$tm=new TopicModel();$db=db_connect();foreach($subjects as $subject){$g=$groupById[$subject['content_group_id']];$apps=$db->query('SELECT o.id,o.name,o.is_selected,oc.weight FROM option_content_groups oc JOIN selectable_options o ON o.id=oc.option_id WHERE oc.content_group_id=?',[$g['id']])->getResultArray();$active=self::databaseBoolean($g['applies_to_all'])||array_filter($apps,static fn($a)=>self::databaseBoolean($a['is_selected']));$weights=array_values(array_filter(array_column($apps,'weight'),static fn($v)=>$v!==null));$topicos=[];foreach($tm->where('subject_id',$subject['id'])->orderBy('sort_order')->findAll() as $topic){$q=$db->query('SELECT COALESCE(SUM(correct_answers),0) acertos,COALESCE(SUM(wrong_answers),0) erros FROM study_sessions WHERE topic_id=?',[$topic['id']])->getRowArray();$topicos[]=['id'=>(string)$topic['id'],'nome'=>$topic['name'],'dificuldade'=>(int)$topic['difficulty'],'posicaoCurva'=>(int)$topic['curve_position'],'primeiraRevisao'=>$topic['first_reviewed_at'],'ultimaRevisao'=>$topic['last_reviewed_at'],'questoes'=>['acertos'=>(int)$q['acertos'],'erros'=>(int)$q['erros']]];}$materias[]=['id'=>(string)$subject['id'],'areaId'=>(string)$g['id'],'nome'=>$subject['name'],'grupoNome'=>$g['name'],'tipoConhecimento'=>$g['knowledge_type'],'selecionada'=>(bool)$active,'opcaoIds'=>array_map(static fn($a)=>(string)$a['id'],$apps),'peso'=>(int)($weights===[]?$subject['weight']:max($weights)),'cor'=>(int)$subject['color'],'topicos'=>$topicos];}}
  $sessoes=[];foreach(($notice?(new StudySessionModel())->select('study_sessions.*')->join('topics','topics.id=study_sessions.topic_id')->join('subjects','subjects.id=topics.subject_id')->where('study_sessions.user_id',$uid)->where('subjects.notice_id',$notice['id'])->orderBy('studied_on')->findAll():[]) as $s)$sessoes[]=['id'=>(string)$s['id'],'materiaId'=>'','topicoId'=>(string)$s['topic_id'],'data'=>$s['studied_on'],'tempoMinutos'=>(int)$s['minutes'],'acertos'=>(int)$s['correct_answers'],'erros'=>(int)$s['wrong_answers'],'dificuldade'=>(int)$s['difficulty']];$availability=['segunda'=>0,'terca'=>0,'quarta'=>0,'quinta'=>0,'sexta'=>0,'sabado'=>0,'domingo'=>0];$dayKeys=array_keys($availability);foreach((new AvailabilityModel())->where('user_id',$uid)->findAll() as $a){$weekday=(int)$a['weekday'];if(isset($dayKeys[$weekday]))$availability[$dayKeys[$weekday]]=(int)$a['minutes']/60;}$profile=(new StudyProfileModel())->find($uid);
  return $this->respond(['edital'=>$notice?['id'=>$notice['id'],'nome'=>$notice['title'],'status'=>$notice['status'],'temConteudoProgramatico'=>$notice['has_study_syllabus']===null?null:self::databaseBoolean($notice['has_study_syllabus'])]:null,'opcoes'=>$opcoes,'areas'=>$opcoes,'materias'=>$materias,'sessoes'=>$sessoes,'configuracao'=>['disponibilidade'=>$availability,'metas'=>['questoesPorSemana'=>(int)($profile['weekly_question_goal']??0),'minutosPorSemana'=>(int)($profile['weekly_minutes_goal']??0)]]]); }
}
